from fractions import Fraction
from itertools import product
from typing import Sequence, Tuple

def occurrence_count(volume: Sequence[int], pattern: Sequence[int]) -> int:
    """Number of starting offsets i in [0, L-k] where pattern occurs in volume."""
    k, L = len(pattern), len(volume)
    return sum(1 for i in range(L - k + 1)
               if all(volume[i + j] == pattern[j] for j in range(k)))

def expected_substring_count(b: int, L: int, k: int) -> Fraction:
    """Closed form (Theorem 3): E[occurrences] = (L-k+1) * b^-k."""
    return Fraction(L - k + 1) * Fraction(1, b ** k)

def verify(b: int, L: int, pattern: Tuple[int, ...]) -> None:
    k = len(pattern)
    total = sum(occurrence_count(v, pattern) for v in product(range(b), repeat=L))
    empirical = Fraction(total, b ** L)
    closed = expected_substring_count(b, L, k)
    assert empirical == closed, (empirical, closed)
    print(f"b={b} L={L} pattern={pattern}: E = {closed} (brute {empirical}) OK")

if __name__ == "__main__":
    verify(2, 4, (1, 0))
    verify(3, 3, (2, 2))
    verify(4, 4, (0, 1))

import math
from fractions import Fraction

def expected_substring_count(b: int, L: int, k: int) -> Fraction:
    """Theorem 3: expected occurrences of a length-k pattern in a length-L book."""
    return Fraction(L - k + 1) * Fraction(1, b ** k)

def contains_bound(b: int, L: int, k: int) -> Fraction:
    """Theorem 4: union-bound upper estimate for containment probability."""
    return Fraction(L - k + 1) * Fraction(1, b ** k)

def borges_report() -> None:
    b, L = 25, 1_312_000
    print(f"Library size 25^1312000 has about {int(L*math.log10(b))+1:,} digits")
    for k in (1, 2, 4, 8, 11, 16, 32):
        e = expected_substring_count(b, L, k)
        print(f"  k={k:>2}: E[occurrences]={float(e):.3e}  "
              f"Pr(contains)<= {float(contains_bound(b,L,k)):.3e}")
        # critical length where E = 1
    print(f"  critical length for k=11 fragment: L* ~ 25^11 = {25**11:,}")

if __name__ == "__main__":
    borges_report()

